using DomainRelay.Abstractions;using DriveOS.Application.Abstractions.Authentication;using DriveOS.Modules.CurriculumPedagogy.Application.RemediationPlans;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;
namespace DriveOS.Api.Endpoints.CurriculumPedagogy;
internal static class RemediationPlanEndpoints{internal static RouteGroupBuilder MapRemediationPlanEndpoints(this RouteGroupBuilder g){g.MapGet("/training-paths/{trainingPathId:guid}/remediation-plans",List).RequireAuthorization("Pedagogy.RemediationPlans.Read");g.MapGet("/remediation-plans/{planId:guid}",Get).RequireAuthorization("Pedagogy.RemediationPlans.Read");g.MapPost("/training-paths/{trainingPathId:guid}/remediation-plans",Create).RequireAuthorization("Pedagogy.RemediationPlans.Manage");g.MapPost("/remediation-plans/{planId:guid}/activate",Activate).RequireAuthorization("Pedagogy.RemediationPlans.Manage");g.MapPost("/remediation-plans/{planId:guid}/complete",Complete).RequireAuthorization("Pedagogy.RemediationPlans.Manage");g.MapPost("/remediation-plans/{planId:guid}/cancel",Cancel).RequireAuthorization("Pedagogy.RemediationPlans.Manage");return g;}private static IResult Fail(Error e)=>Results.Problem(statusCode:e.Type==ErrorType.NotFound?404:e.Type==ErrorType.Conflict?409:400,title:e.Code,detail:e.MessageKey);private static bool Ctx(ICurrentTenant t,ICurrentUser u,out OrganizationId o,out UserId a){o=t.OrganizationId??OrganizationId.Empty;a=u.UserId??UserId.Empty;return !o.IsEmpty&&!a.IsEmpty;}private static async Task<IResult>List(Guid trainingPathId,IRemediationPlanReadService r,ICurrentTenant t,CancellationToken ct){if(t.OrganizationId is not{}o)return Results.Unauthorized();return Results.Ok(await r.ListAsync(o,new TrainingPathId(trainingPathId),ct));}private static async Task<IResult>Get(Guid planId,IRemediationPlanReadService r,ICurrentTenant t,CancellationToken ct){if(t.OrganizationId is not{}o)return Results.Unauthorized();var x=await r.GetAsync(o,new RemediationPlanId(planId),ct);return x is null?Results.NotFound():Results.Ok(x);}private static async Task<IResult>Create(Guid trainingPathId,CreateRemediationPlanRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(!Ctx(t,u,out var o,out var a))return Results.Unauthorized();var targets=q.Targets.Select(x=>new RemediationTargetRequest(new CompetencyId(x.CompetencyId),x.Objective)).ToArray();var x=await m.Send(new CreateRemediationPlanCommand(o,new TrainingPathId(trainingPathId),new UserId(q.ResponsibleUserId??a.Value),q.SourcePedagogicalReviewId.HasValue?new PedagogicalReviewId(q.SourcePedagogicalReviewId.Value):null,q.Recommendation,q.RecommendedPracticalHours,q.RecommendedSessions,q.ReviewDate,targets),ct);return x.IsSuccess?Results.Created($"/api/pedagogy/remediation-plans/{x.Value.Value}",new{id=x.Value.Value}):Fail(x.Error);}private static async Task<IResult>Activate(Guid planId,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(!Ctx(t,u,out var o,out _))return Results.Unauthorized();var x=await m.Send(new ActivateRemediationPlanCommand(o,new RemediationPlanId(planId)),ct);return x.IsSuccess?Results.NoContent():Fail(x.Error);}private static async Task<IResult>Complete(Guid planId,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(!Ctx(t,u,out var o,out _))return Results.Unauthorized();var x=await m.Send(new CompleteRemediationPlanCommand(o,new RemediationPlanId(planId)),ct);return x.IsSuccess?Results.NoContent():Fail(x.Error);}private static async Task<IResult>Cancel(Guid planId,CancelRemediationPlanRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(!Ctx(t,u,out var o,out _))return Results.Unauthorized();var x=await m.Send(new CancelRemediationPlanCommand(o,new RemediationPlanId(planId),q.Reason),ct);return x.IsSuccess?Results.NoContent():Fail(x.Error);}}
public sealed record RemediationTargetApiRequest(Guid CompetencyId,string Objective);public sealed record CreateRemediationPlanRequest(Guid? ResponsibleUserId,Guid? SourcePedagogicalReviewId,string Recommendation,decimal? RecommendedPracticalHours,int? RecommendedSessions,DateOnly ReviewDate,IReadOnlyCollection<RemediationTargetApiRequest> Targets);public sealed record CancelRemediationPlanRequest(string Reason);
